#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=2310 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap2310
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=4620 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap4620
set -euo pipefail
